```python
def count_integers(lst):
    # Create an empty dictionary to store integer counts
    int_counts = {}

    # Iterate through each element in the list
    for num in lst:
        # If the number is already in the dictionary, increment its count
        if num in int_counts:
            int_counts[num] += 1
        else:
            # Otherwise, add the number as a key with a count of 1
            int_counts[num] = 1

    # Return the dictionary containing the counts
    return int_counts

